import * as THREE from './vendor/three.module.js';
import {BASIC_ATTACKS} from './runner-basic-attacks.js?v=basic-attacks-258';
export class RunnerBasicFX {
 constructor(scene){this.colors=new Map();this.root=new THREE.Group();scene.add(this.root);this.dummy=new THREE.Object3D();this.up=new THREE.Vector3(0,1,0);const mat=(opacity)=>new THREE.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity,depthWrite:false,blending:THREE.AdditiveBlending,toneMapped:false}),geometry=new THREE.CylinderGeometry(1,1,1,5,1,true);this.core=new THREE.InstancedMesh(geometry,mat(.95),384);this.glow=new THREE.InstancedMesh(geometry,mat(.25),384);this.flashes=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,0),mat(.8),48);for(const p of[this.core,this.glow,this.flashes]){p.frustumCulled=false;this.root.add(p);}this.clear();}
 color(value){if(!this.colors.has(value))this.colors.set(value,new THREE.Color(value));return this.colors.get(value);}
 clear(){this.core.count=this.glow.count=this.flashes.count=0;}
 sound(audio,weapon){if(!audio||audio.state!=='running')return;try{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime,d=weapon==='sweep'?.12:.045;o.type=weapon==='sweep'?'sawtooth':'triangle';o.frequency.setValueAtTime(weapon==='needle'?1600:weapon==='sparks'?850:440,t);o.frequency.exponentialRampToValueAtTime(weapon==='sweep'?80:weapon==='needle'?700:200,t+d);g.gain.setValueAtTime(weapon==='sparks'?.012:.03,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(audio.destination);o.onended=()=>{o.disconnect();g.disconnect();};o.start();o.stop(t+d+.01);}catch{}}
 update(controller,time){const segments=[],flashes=[],line=(a,b,width,color)=>segments.push({a,b,width,color});for(const p of controller.projectiles){const c=BASIC_ATTACKS[p.weapon],length=p.weapon==='needle'?2.4:p.weapon==='sparks'?.65:1.3;line(p.position.clone().addScaledVector(p.direction,-Math.min(p.traveled+.1,length)),p.position,c.radius,c.color);line(p.position.clone().addScaledVector(p.direction,-Math.min(p.traveled+.1,length*2)),p.position,c.radius*.4,c.color);}
  for(const e of controller.effects){const life=e.kind==='muzzle'?.045:.16,fade=Math.max(0,1-e.age/life);if(e.kind==='sweep'){const yaw=Math.atan2(e.direction.x,e.direction.z),radius=BASIC_ATTACKS.sweep.range;let last=null;for(let i=0;i<=24;i++){const a=yaw+(-BASIC_ATTACKS.sweep.arc/2+i*BASIC_ATTACKS.sweep.arc/24)*Math.PI/180,p=e.point.clone().add(new THREE.Vector3(Math.sin(a)*radius,Math.sin(i*4+time*60)*.06,Math.cos(a)*radius));if(last)line(last,p,.04*fade,e.color);last=p;}continue;}if(e.kind==='muzzle'){flashes.push({p:e.point,size:.12*fade,color:e.color});continue;}const size=e.weak?.9:.35;flashes.push({p:e.point,size:fade*(e.weak?.2:.08),color:e.weak?'#fff3b0':e.color});for(let i=0;i<6;i++){const a=i*Math.PI/3,d=new THREE.Vector3(Math.cos(a),Math.sin(a),Math.sin(i*3.1)).normalize();line(e.point.clone().addScaledVector(d,size*(1-fade)),e.point.clone().addScaledVector(d,size*(1-fade+.35)),.012*fade,e.weak?'#fff3b0':e.color);}}
  let n=0;for(const s of segments){if(n>=384)break;const d=s.b.clone().sub(s.a);if(d.lengthSq()<1e-10)continue;this.dummy.position.copy(s.a).lerp(s.b,.5);this.dummy.quaternion.setFromUnitVectors(this.up,d.clone().normalize());this.dummy.scale.set(s.width,d.length(),s.width);this.dummy.updateMatrix();this.core.setMatrixAt(n,this.dummy.matrix);this.core.setColorAt(n,this.color(s.color));this.dummy.scale.x=this.dummy.scale.z=s.width*3;this.dummy.updateMatrix();this.glow.setMatrixAt(n,this.dummy.matrix);this.glow.setColorAt(n,this.color(s.color));n++;}this.core.count=this.glow.count=n;for(const p of[this.core,this.glow]){p.instanceMatrix.needsUpdate=true;if(p.instanceColor)p.instanceColor.needsUpdate=true;}
  n=0;for(const f of flashes){if(n>=48)break;this.dummy.position.copy(f.p);this.dummy.quaternion.identity();this.dummy.scale.setScalar(f.size);this.dummy.updateMatrix();this.flashes.setMatrixAt(n,this.dummy.matrix);this.flashes.setColorAt(n,this.color(f.color));n++;}this.flashes.count=n;this.flashes.instanceMatrix.needsUpdate=true;if(this.flashes.instanceColor)this.flashes.instanceColor.needsUpdate=true;
 }
 diagnostics(){return{segments:this.core.count,flashes:this.flashes.count,drawCalls:(this.core.count?2:0)+(this.flashes.count?1:0)};}
}
